from __future__ import annotations

# =============================================================================
# Code_Details_Questions.py
# NHANES questionnaire catalog (same contract as Code_Details_Diet / Lab).
# Built from questions_combined_1.pdf .. questions_combined_13.pdf.
#
# Those books cover 1999-2000 through August 2021-August 2023,
# including the 2017-March 2020 pre-pandemic files.
# Columns with no codebook in the uploaded books are listed in NOT_IN_BOOKS
# and are not given invented codes.
#
# Methodology:
# - Decode each cycle before concatenating. Labels and universes change.
# - Refused / Don't know on numeric items are sentinels, not values.
# - Skip-driven missing is not a substantive No.
# - RXQ_RX / RXQANA are grain='drugs'. PAQIAF is grain='activity'.
# - RXQ_DRUG is a drug lexicon used to decode RXDDRGID.
# - Interview weight is the default questionnaire weight unless the file
#   note says MEC / subsample (see each spec notes and QUESTION_FILES).
# =============================================================================

CYCLES = [
    "99-00", "01-02", "03-04", "05-06", "07-08", "09-10",
    "11-12", "13-14", "15-16", "17-18", "17-20", "21-23",
]

T_ALL = "Both males and females 0 YEARS - 150 YEARS"
YES_NO = {1: "Yes", 2: "No", 7: "Refused", 9: "Don't know"}

NOT_IN_BOOKS = []

def _var(
    short, sas, kind, text, target, codes=None, sas_by_cycle=None,
    codes_by_cycle=None, label=None, notes=None, raw_codes=None,
    raw_codes_by_cycle=None, target_by_cycle=None, definition=None,
    definition_by_cycle=None, tables=None, aliases=None, kind_by_cycle=None,
    group=None, cycles=None,
):
    return {
        "short": short,
        "sas": sas,
        "kind": kind,
        "text": text,
        "label": label or text,
        "target": target,
        "codes": None if codes is None else dict(codes),
        "sas_by_cycle": dict(sas_by_cycle or {}),
        "codes_by_cycle": dict(codes_by_cycle or {}),
        "notes": notes or "",
        "raw_codes": None if raw_codes is None else dict(raw_codes),
        "raw_codes_by_cycle": dict(raw_codes_by_cycle or {}),
        "target_by_cycle": dict(target_by_cycle or {}),
        "definition": definition or "",
        "definition_by_cycle": dict(definition_by_cycle or {}),
        "tables": tuple(tables or ()),
        "day_pair": None,
        "aliases": list(aliases or []),
        "kind_by_cycle": dict(kind_by_cycle or {}),
        "group": group or "",
        "cycles": list(cycles or []),
    }

