def _index_sas(index, sas, short):
    if sas:
        index[str(sas)] = short

SAS_TO_SHORT_QUESTIONS = {}
for _spec in QUESTION_VARS.values():
    _index_sas(SAS_TO_SHORT_QUESTIONS, _spec.get('sas'), _spec['short'])
    for _alias in (_spec.get('sas_by_cycle') or {}).values():
        _index_sas(SAS_TO_SHORT_QUESTIONS, _alias, _spec['short'])
    for _alias in _spec.get('aliases') or []:
        _index_sas(SAS_TO_SHORT_QUESTIONS, _alias, _spec['short'])

