QUESTION_GROUPS = sorted({spec['group'] for spec in QUESTION_VARS.values()})

_QUESTION_TABLES = {}
for _stem, _meta in QUESTION_FILES.items():
    _QUESTION_TABLES[_stem] = {'grain': _meta['grain'], 'component': _meta['component'], 'cycles': tuple(_meta['cycles'])}

# RXQ_DRUG is a lexicon, not a person or drug-event table.
# RXQ_RX.RXDDRGID joins to RXQ_DRUG.RXDDRGID; decode_rows replaces the code with RXDDRUG.
DRUG_LOOKUP_TABLE = "RXQ_DRUG"
DRUG_CODE_COLUMNS = ("RXDDRGID",)
DRUG_NAME_COLUMN = "RXDDRUG"
DRUG_GRAIN = "drugs"

QUESTION_CATALOG = {
    "name": "questionnaire",
    "aliases": (
        "questionnaire", "questions", "question", "questionaire",
        "interview", "sp questionnaire", "q",
    ),
    "vars": QUESTION_VARS,
    "sas_to_short": SAS_TO_SHORT_QUESTIONS,
    "grain": "person",
    "groups": QUESTION_GROUPS,
    "tables": _QUESTION_TABLES,
}

def sas_name(spec, cycle=None, day=1):
    if cycle and cycle in spec.get('sas_by_cycle', {}):
        return spec['sas_by_cycle'][cycle]
    return spec.get('sas')

def codes_for(spec, cycle=None):
    if cycle and cycle in (spec.get('codes_by_cycle') or {}):
        return spec['codes_by_cycle'][cycle]
    return spec.get('codes')

def raw_codes_for(spec, cycle=None):
    raw_by = spec.get('raw_codes_by_cycle') or {}
    if cycle and cycle in raw_by:
        return raw_by[cycle]
    if spec.get('raw_codes'):
        return spec['raw_codes']
    return codes_for(spec, cycle)

def kind_for(spec, cycle=None):
    by = spec.get('kind_by_cycle') or {}
    if cycle and cycle in by:
        return by[cycle]
    return spec['kind']

def target_for(spec, cycle=None):
    by = spec.get('target_by_cycle') or {}
    if cycle and cycle in by:
        return by[cycle]
    return spec.get('target') or ''

def definition_for(spec, cycle=None):
    by = spec.get('definition_by_cycle') or {}
    if cycle and cycle in by:
        return by[cycle]
    return spec.get('definition') or spec.get('text') or ''

def notes_for(spec):
    return spec.get('notes') or ''

def sentinel_codes(spec, cycle=None):
    """Refused / Don't know codes. Not for use as numeric measurements."""
    found = []
    for mapping in (raw_codes_for(spec, cycle) or {}, codes_for(spec, cycle) or {}):
        for key, label in mapping.items():
            if str(label).strip().lower() in {'refused', "don't know", 'dont know'}:
                if key not in found:
                    found.append(key)
    return found

def mask_sentinels(df, cycle=None, vars_map=None):
    """Set refused/don't-know sentinels to missing on count/continuous items."""
    import pandas as pd
    out = df.copy()
    lookup = vars_map or QUESTION_VARS
    sas_to_short = {spec['sas']: spec for spec in lookup.values()}
    short_to = {spec['short']: spec for spec in lookup.values()}
    for col in list(out.columns):
        spec = sas_to_short.get(str(col)) or short_to.get(str(col))
        if not spec:
            continue
        if kind_for(spec, cycle) not in {'continuous', 'count', 'derived', 'weight'}:
            continue
        sentinels = sentinel_codes(spec, cycle)
        if not sentinels:
            continue
        num = pd.to_numeric(out[col], errors='coerce')
        mask = False
        for code in sentinels:
            try:
                mask = mask | (num == float(code))
            except (TypeError, ValueError):
                continue
        if getattr(mask, 'any', lambda: False)():
            out.loc[mask, col] = pd.NA
    return out


